function activePackage(){return drillPackages.find(function(p){return p.id===activeDrillPackageId;})||null;}
function safeText(s){return String(s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}
function updateContentTracker(){
 const topicTotal=levels.filter(function(l){return !l.type;}).length;
 const topicsReady=Object.keys(lessonData).map(Number).filter(function(i){return i<topicTotal;}).length;
 const mainPackages=drillPackages.filter(function(p){return p.category!=="bab"&&p.category!=="prediksi";});
 const questionTotal=mainPackages.reduce(function(sum,p){return sum+p.totalQuestions;},0);
 const questionsReady=mainPackages.reduce(function(sum,p){return sum+p.questions.length;},0);
 if($("contentReadyCount"))$("contentReadyCount").textContent=topicsReady+" / "+topicTotal+" bab";
 if($("drillReadyCount"))$("drillReadyCount").textContent=questionsReady+" / "+questionTotal+" soal";
}
function renderTryout(){
 updateContentTracker();
 const grid=$("packageGrid"),detail=$("packageDetail");
 if(activePackageViewId){
  const pack=drillPackages.find(function(p){return p.id===activePackageViewId;});
  if(!pack){activePackageViewId=null;detail.classList.add("hidden");grid.classList.remove("hidden");return renderTryout();}
  grid.classList.add("hidden");detail.classList.remove("hidden");
  $("packageDetailKicker").textContent=pack.category==="prediksi"?"PREDIKSI BARU · KISI-KISI PUSMENDIK":"TRY OUT & DRILLING · HALAMAN "+pack.pages;
  $("packageDetailTitle").textContent=pack.title;
  $("packageDetailLead").textContent=pack.description;
  $("packageQuestionCount").textContent=pack.questions.length+"/"+pack.totalQuestions;
  $("packageQuestionList").innerHTML=pack.questions.map(function(q,i){const form=q.type==="tf"?"PGK Kategori · Benar/Salah":q.type==="multi"?"PGK MCMA · pilih lebih dari satu":"PG · satu jawaban";const pageLabel=pack.category==="prediksi"?"Prediksi · "+form:"Halaman "+q.page+" · "+form;return '<div class="package-question-row"><div class="question-number">'+String(q.number).padStart(2,"0")+'</div><div class="package-question-copy"><b>Nomor '+q.number+'</b><span>'+pageLabel+'</span><small>'+safeText(q.text).slice(0,145)+(q.text.length>145?"…":"")+'</small></div><button class="secondary-btn start-question" data-question="'+i+'">Mulai drilling →</button></div>';}).join("")+(pack.pendingNote?'<div class="source-warning"><strong>Catatan sumber</strong><p>'+safeText(pack.pendingNote)+'</p></div>':'');
  document.querySelectorAll(".start-question").forEach(function(btn){btn.addEventListener("click",function(){startDrill(pack.id,Number(btn.dataset.question));});});
  return;
 }
 detail.classList.add("hidden");grid.classList.remove("hidden");
 const visible=drillPackages.filter(function(p){return activePackageFilter==="semua"||p.category===activePackageFilter;});
 grid.innerHTML=visible.map(function(p){const pct=Math.min(100,Math.round(p.questions.length/p.totalQuestions*100));const pageLabel=p.category==="prediksi"?"KISI-KISI RESMI": "HLM. "+p.pages;const categoryLabel=p.category==="latihan"?"LATIHAN TERARAH":p.category==="prediksi"?"LATIHAN PREDIKSI · BUKAN SOAL RESMI":p.category.toUpperCase();return '<article class="package-card '+(p.questions.length?"has-questions":"pending-package")+'"><div class="package-card-top"><span class="package-symbol">'+(p.category==="latihan"?"▣":p.category==="simulasi"?"◈":p.category==="prediksi"?"✦":"◇")+'</span><span class="package-page">'+pageLabel+'</span></div><div class="section-kicker">'+categoryLabel+'</div><h3>'+p.title+'</h3><p>'+safeText(p.description)+'</p><div class="package-meter"><span style="width:'+pct+'%"></span></div><div class="package-card-foot"><span><b>'+p.questions.length+'</b> / '+p.totalQuestions+' soal masuk</span><span class="package-ready">'+(p.questions.length?"BISA DRILLING":"MENUNGGU")+'</span></div><button class="secondary-btn package-open" data-pack="'+p.id+'">'+(p.questions.length?"Buka paket →":"Lihat status →")+'</button></article>';}).join("");
 document.querySelectorAll(".package-open").forEach(function(btn){btn.addEventListener("click",function(){openPackage(btn.dataset.pack);});});
}
function openPackage(id){activePackageViewId=id;renderTryout();}
function openPackageFromLevel(index){const pack=drillPackages[Math.max(0,Math.min(drillPackages.length-1,index))];activePackageFilter="semua";document.querySelectorAll(".filter-chip").forEach(function(b){b.classList.toggle("active",b.dataset.filter==="semua");});openPackage(pack.id);showView("tryoutView");}
function startDrill(packId,questionIndex){
 const pack=drillPackages.find(function(p){return p.id===packId;});if(!pack||!pack.questions[questionIndex])return;
 activeDrillPackageId=packId;activeDrillIndex=questionIndex;activeQuestion=pack.questions[questionIndex];
 renderQuiz();showView("quizView");
}
function continueFromQuiz(){
 if(activeDrillPackageId){
  const pack=activePackage();
  if(pack&&activeDrillIndex+1<pack.questions.length){activeDrillIndex++;activeQuestion=pack.questions[activeDrillIndex];renderQuiz();showView("quizView");return;}
  const id=activeDrillPackageId;activeDrillPackageId=null;activeQuestion=null;activeDrillIndex=0;activePackageViewId=id;renderTryout();showView("tryoutView");return;
 }
 renderMap();showView("mapView");
}
document.querySelectorAll(".filter-chip").forEach(function(btn){btn.addEventListener("click",function(){activePackageFilter=btn.dataset.filter;document.querySelectorAll(".filter-chip").forEach(function(b){b.classList.toggle("active",b===btn);});activePackageViewId=null;renderTryout();});});
$("backToPackages").addEventListener("click",function(){activePackageViewId=null;renderTryout();});
// Replace previous lesson-only handlers: the drill screen supports multiple response types.
["hintButton","nextHint","checkAnswer","continueAfterQuiz","backToLesson"].forEach(function(id){
 const node=$(id),copy=node.cloneNode(true);node.replaceWith(copy);
});
$("hintButton").addEventListener("click",showHint);
$("nextHint").addEventListener("click",showHint);
$("checkAnswer").addEventListener("click",checkAnswer);
$("continueAfterQuiz").addEventListener("click",continueFromQuiz);
$("backToLesson").addEventListener("click",function(){showView(activeDrillPackageId?"tryoutView":"lessonView");});
function renderQuiz(){
 const q=activeQuestion||lessonData[selected].quiz;
 answerSelected=q.type==="tf"?new Array(q.statements.length).fill(null):q.type==="multi"?[]:null;
 hintIndex=0;attempted=false;stopSpeech();
 const pack=activeDrillPackageId?activePackage():null;
 $("quizTopic").textContent=pack?pack.title.toUpperCase()+" · SOAL "+q.number:"LEVEL "+String(selected+1).padStart(2,"0");
 $("quizCounter").textContent=pack?"SOAL "+(activeDrillIndex+1)+" / "+pack.questions.length+(pack.category==="prediksi"?" · KOMPETENSI TKA":q.page?" · HLM. "+q.page:""):"KUIS PEMAHAMAN · 1 SOAL";
 $("quizProgressFill").style.width=pack?Math.round(activeDrillIndex/pack.questions.length*100)+"%":"0%";
 $("questionText").textContent=q.text;
 const cognitiveLabel={1:"Level 1 · Pemahaman",2:"Level 2 · Penerapan",3:"Level 3 · Analisis dan Evaluasi"};
  const mapping=q.competency?"\nPemetaan Pusmendik: "+q.competency+" · "+(cognitiveLabel[q.level]||"Level kognitif belum ditandai")+".":"";
  $("questionContext").textContent=(q.context||"")+(q.page?" · Sumber buku: hlm. "+q.page+".":"")+mapping;
 if(q.type==="tf"){
  $("choices").innerHTML=q.statements.map(function(s,i){return '<div class="tf-row"><div class="tf-statement"><span class="tf-index">'+(i+1)+'</span><span>'+safeText(s)+'</span></div><div class="tf-buttons"><button class="tf-option" data-tf-index="'+i+'" data-tf-value="true">Benar</button><button class="tf-option" data-tf-index="'+i+'" data-tf-value="false">Salah</button></div></div>';}).join("");
  document.querySelectorAll(".tf-option").forEach(function(b){b.addEventListener("click",function(){if(attempted)return;const i=Number(b.dataset.tfIndex);answerSelected[i]=b.dataset.tfValue==="true";document.querySelectorAll('.tf-option[data-tf-index="'+i+'"]').forEach(function(x){x.classList.toggle("selected",x===b);});$("quizFeedback").classList.add("hidden");});});
 }else{
  $("choices").innerHTML=q.choices.map(function(c,i){return '<button class="choice" data-choice="'+i+'"><span class="choice-mark">'+(q.type==="multi"?"□":String.fromCharCode(65+i))+'</span><span>'+safeText(c)+'</span></button>';}).join("");
  document.querySelectorAll(".choice").forEach(function(b){b.addEventListener("click",function(){if(attempted)return;const i=Number(b.dataset.choice);if(q.type==="multi"){const arr=answerSelected.slice(),pos=arr.indexOf(i);if(pos>=0)arr.splice(pos,1);else arr.push(i);answerSelected=arr.sort(function(a,b){return a-b;});document.querySelectorAll(".choice").forEach(function(x){x.classList.toggle("selected",answerSelected.includes(Number(x.dataset.choice)));});}else{answerSelected=i;document.querySelectorAll(".choice").forEach(function(x){x.classList.toggle("selected",x===b);});}$("quizFeedback").classList.add("hidden");});});
 }
 $("quizFeedback").className="quiz-feedback hidden";$("hintBox").classList.add("hidden");$("hintButton").disabled=false;$("checkAnswer").disabled=false;$("checkAnswer").classList.remove("hidden");$("quizComplete").classList.add("hidden");$("choices").classList.remove("hidden");
 $("hintButton").textContent="Bingung? Beri tahu caranya";$("nextHint").textContent="Petunjuk berikutnya";$("nextHint").disabled=false;
 const practiceOnly=q.sourceType==="practice"||/kuis pemahaman|latihan pemahaman|bukan salinan|disusun ulang|latihan interpretasi/i.test(q.context||"");
 $("quizSourceTag").textContent=pack?(pack.category==="prediksi"?"SOAL PREDIKSI IRZA LEARNING · BUKAN SOAL RESMI / BOCORAN":practiceOnly?"LATIHAN BERDASARKAN BUKU · P"+q.page+" · BUKAN SALINAN UTUH":"SOAL BUKU YANG DIALIHMASUKKAN · P"+q.page+" · KUNCI TIDAK DITAMPILKAN SEBELUM MENJAWAB"):"KUIS PEMAHAMAN MATERI · SOAL LATIHAN, BUKAN SOAL ASLI BUKU";
 $("quizComplete").querySelector("h3").textContent=pack?"Soal berhasil dikerjakan":"Kuis materi selesai";
 $("continueAfterQuiz").textContent=pack?"Lanjut soal berikutnya →":"Kembali ke peta →";
}
function showHint(){
 if(attempted)return;
 const q=activeQuestion||lessonData[selected].quiz,hints=q.hints||[];
 if(!hints.length){$("hintBox").classList.remove("hidden");$("hintText").textContent="Identifikasi dulu informasi yang diketahui, konsep yang digunakan, dan apa yang ditanyakan. Susun rumusnya, lalu lanjutkan hitunganmu sendiri.";$("hintStep").textContent="1/1";return;}
 $("hintBox").classList.remove("hidden");$("hintText").textContent=hints[hintIndex];$("hintStep").textContent=(hintIndex+1)+"/"+hints.length;hintIndex=(hintIndex+1)%hints.length;$("nextHint").textContent=hintIndex===0?"Ulangi petunjuk":"Petunjuk berikutnya";
}
function checkAnswer(){
 const q=activeQuestion||lessonData[selected].quiz;
 let complete=false,correct=false;
 if(q.type==="tf"){
  complete=Array.isArray(answerSelected)&&answerSelected.length===q.statements.length&&answerSelected.every(function(v){return v===true||v===false;});
  correct=complete&&answerSelected.every(function(v,i){return v===q.answer[i];});
 }else if(q.type==="multi"){
  complete=Array.isArray(answerSelected)&&answerSelected.length>0;
  correct=complete&&answerSelected.length===q.answer.length&&answerSelected.every(function(v,i){return v===q.answer[i];});
 }else{
  complete=answerSelected!==null&&answerSelected!==undefined;
  correct=complete&&answerSelected===q.answer;
 }
 if(!complete){$("quizFeedback").className="quiz-feedback";$("quizFeedback").textContent=q.type==="tf"?"Pilih Benar atau Salah untuk setiap pernyataan. Kamu bisa meminta petunjuk jika bingung.":q.type==="multi"?"Pilih minimal satu jawaban. Soal ini bisa memiliki lebih dari satu jawaban benar.":"Pilih jawaban terlebih dahulu. Kamu boleh membuka petunjuk bertahap.";return;}
 if(correct){
  attempted=true;$("quizFeedback").className="quiz-feedback good";$("quizFeedback").textContent="Benar. Jawabanmu sudah dicatat. Lanjutkan ke soal berikutnya jika masih ada.";
  state.attempts++;
  if(activeQuestion){
   if(!Array.isArray(state.drillPassed))state.drillPassed=[];
   const key=activeDrillPackageId+":"+activeQuestion.id;
   if(!state.drillPassed.includes(key))state.drillPassed.push(key);
  }else{
   if(!state.passed.includes(selected))state.passed.push(selected);
   state.unlocked=Math.max(state.unlocked,selected+1);
  }
  save();$("quizProgressFill").style.width="100%";$("hintButton").disabled=true;$("checkAnswer").disabled=true;$("choices").classList.add("hidden");$("quizComplete").classList.remove("hidden");
  if(activeQuestion){
   const pack=activePackage(),next=pack&&activeDrillIndex+1<pack.questions.length;
   $("quizComplete").querySelector("p").textContent=next?"Jawaban dicatat untuk soal ini. Setelah lanjut, soal berikutnya dalam "+pack.title+" akan terbuka. Kunci tidak ditampilkan dalam daftar soal.":"Semua soal digital pada bagian paket ini sudah kamu kerjakan. Soal yang belum didigitalisasi tetap tercatat sebagai pekerjaan berikutnya.";
   $("continueAfterQuiz").textContent=next?"Lanjut soal berikutnya →":"Kembali ke paket →";
  }else{
   const next=levels[selected+1];
   $("quizComplete").querySelector("p").textContent=next?"Kuis materi selesai. Kamu tetap bebas memilih bab lain dari peta belajar.":"Kuis materi selesai.";
  }
  renderMap();
 }else{
  $("quizFeedback").className="quiz-feedback";$("quizFeedback").textContent="Belum tepat. Kunci tidak dibocorkan. Periksa data dan konsep yang relevan, gunakan petunjuk bertahap, lalu coba lagi.";
  state.attempts++;save();
 }
}
